import java.util.*;
import java.math.*;

public class Main {
    static long power(long base, int exp, int mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        int MO = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(power(k, n, MO));
            return;
        }

        long[] factorial = new long[n + 1];
        long[] inv_factorial = new long[n + 1];
        factorial[0] = 1;
        for (int i = 1; i <= n; ++i) {
            factorial[i] = (factorial[i - 1] * i) % MO;
        }
        inv_factorial[n] = power(factorial[n], MO - 2, MO);
        for (int i = n - 1; i >= 0; --i) {
            inv_factorial[i] = (inv_factorial[i + 1] * (i + 1)) % MO;
        }

        int t = n;
        List<Integer> a = new ArrayList<>();
        for (int i = 0; i <= 20; ++i) {
            if ((t & 1) == 1) a.add(1 << i);
            t >>= 1;
        }

        int S_size = 1 << a.size();
        int[] S = new int[S_size];
        for (int i = 0; i < S_size; ++i) {
            int sum = 0;
            for (int j = 0; j < a.size(); ++j) {
                if (((i >> j) & 1) == 1) sum += a.get(j);
            }
            S[i] = sum;
        }

        int[] p = new int[S_size];
        for (int i = 0; i < S_size; ++i) {
            int t_idx = -1;
            for (int j = 0; j <= 20; ++j) {
                if (((i >> j) & 1) == 1) t_idx = j;
            }
            p[i] = (1 << (t_idx + 1)) + i;
        }

        long[][] f = new long[k + 1][S_size];
        f[0][0] = 1;

        for (int i = 0; i < k; ++i) {
            for (int j = 0; j < S_size; ++j) {
                if (f[i][j] != 0) {
                    for (int k_idx = p[j]; k_idx < S_size; k_idx = (k_idx + 1) | j) {
                        int diff = S[k_idx ^ j];
                        long inv_val = inv_factorial[diff];
                        f[i + 1][k_idx] = (f[i + 1][k_idx] + f[i][j] * inv_val) % MO;
                    }
                }
            }
        }

        long ans = 0;
        for (int i = 0; i <= k; ++i) {
            long comb = (factorial[k] * inv_factorial[i] % MO) * inv_factorial[k - i] % MO;
            ans = (ans + f[i][S_size - 1] * comb) % MO;
        }

        ans = (ans * factorial[n]) % MO;
        long total = power(k, n, MO);
        long result = (total - ans + MO) % MO;
        System.out.println(result);
    }
}
